function o(e){return[{texto:`Entre 12 y 200 caracteres`,cumple:e.length>=12&&e.length<=200},{texto:`Al menos una minúscula`,cumple:new RegExp(`\\p{Ll}`,`u`).test(e)},{texto:`Al menos una mayúscula`,cumple:new RegExp(`\\p{Lu}`,`u`).test(e)},{texto:`Al menos un carácter especial (como # ! - .)`,cumple:/[^\p{L}\p{N}\s]/u.test(e)},{texto:`No puede ser solo espacios`,cumple:!/^\s*$/u.test(e)}]}function u(e){return o(e).every(t=>t.cumple)}export{u as n,o as t};